        Ocr.oxBegin(c, 1, 2, 3, -85, 90, 1281455214, 17, 187, 1);
        Ocr.oxLine(c, 10, 18, 70, 44, 10, 60, 80, 62, 0, 0, 1);
        int x0 = Ocr.oxWord(c, 65, 1701734144);
        int s0 = Ocr.oxSym(c, x0, 10, 20, 15, 40, 950);
        Ocr.oxSymCp(c, s0, 72);
        int a0 = Ocr.oxAlt(c, s0, 120);
        Ocr.oxAltCp(c, a0, 75);
        int a1 = Ocr.oxAlt(c, s0, 80);
        Ocr.oxAltCp(c, a1, 78);
        Ocr.oxAltCp(c, a1, 77);
        int s1 = Ocr.oxSym(c, x0, 25, 20, 15, 40, 900);
        Ocr.oxSymCp(c, s1, 105);
        int x1 = Ocr.oxWord(c, 0, 0);
        int s2 = Ocr.oxSym(c, x1, 50, 20, 30, 40, 800);
        Ocr.oxSymCp(c, s2, 33);
        Plan.anOcrEnd(c, at);
        int ext = Ocr.oxFind(c, at);
        emon.Testport.assertThat(ext >= 0, "the extension is found after the two words");
        int n1 = Plan.awNext(c, w0);
        emon.Testport.assertEq(ext, Plan.awNext(c, n1), "right after the last word");
        emon.Testport.assertEq(Ocr.oxGet(c, ext, 0), Ocr.oxVersion(), "version");
        emon.Testport.assertEq(Ocr.oxOrient(c, ext), 1, "orient");
        emon.Testport.assertEq(Ocr.oxWdir(c, ext), 2, "writing direction");
        emon.Testport.assertEq(Ocr.oxTlorder(c, ext), 3, "line order");
        emon.Testport.assertEq(Ocr.oxDeskew(c, ext), -85, "deskew in centi-degrees");
        emon.Testport.assertEq(Ocr.oxOsd(c, ext), 90, "OSD degrees");
