        emon.Testport.assertEq(emon.Port.cellsAt(c, l + 6), 80, "baseline end x");
        emon.Testport.assertEq(emon.Port.cellsAt(c, l + 10), 1, "block type");
        emon.Testport.assertEq(Ocr.oxFirstWord(c, ext), l + Ocr.oxLineStride(), "the word list follows the lines");
        int wx0 = Ocr.oxFirstWord(c, ext);
        emon.Testport.assertEq(Ocr.oxWflags(c, wx0), 65, "bold and mono");
        emon.Testport.assertEq(Ocr.oxWlang(c, wx0), 1701734144, "eng");
        emon.Testport.assertEq(Ocr.oxNsym(c, wx0), 2, "two symbols");
        int sy0 = Ocr.oxFirstSym(c, wx0);
        emon.Testport.assertEq(emon.Port.cellsAt(c, sy0 + 4), 950, "symbol confidence");
        emon.Testport.assertEq(emon.Port.cellsAt(c, sy0 + 5), 1, "one code point");
        emon.Testport.assertEq(emon.Port.cellsAt(c, sy0 + 6), 2, "two alternatives");
        emon.Testport.assertEq(emon.Port.cellsAt(c, sy0 + 7), 72, "H");
        int al0 = Ocr.oxSymAlts(c, sy0);
        int al1 = Ocr.oxAltNext(c, al0);
        emon.Testport.assertEq(emon.Port.cellsAt(c, al0), 1, "the first alternative has one code point");
        emon.Testport.assertEq(emon.Port.cellsAt(c, al0 + 1), 120, "its confidence");
        emon.Testport.assertEq(emon.Port.cellsAt(c, al0 + 2), 75, "K");
        emon.Testport.assertEq(emon.Port.cellsAt(c, al1), 2, "the second has two");
